r exists dmsetup create --noudevsync rf-t --table '0 8 zero'; rt rf-t
r remove-missing dmsetup remove --noudevsync rf-none
r resume-missing dmsetup resume --noudevsync rf-none
printf '0 32 striped 2 8 %s 0 %s 0\n32 16 linear %s 16\n48 8 zero\n56 8 error\n64 24 linear %s 40\n' $d1 $d2 $d1 $d2 > multi.tbl
r multi dmsetup create --noudevsync rf-multi multi.tbl; rt rf-multi; inf rf-multi
