o() { settle; local log=$RT/o.jsonl; : > $log
  PYTHONDONTWRITEBYTECODE=1 /usr/bin/python3 $SQ --notify ioctl:1=0xc138fd06 --notify ioctl:1=0xc138fd04 --notify ioctl:1=0xc138fd0a \
    --notify ioctl:1=0xc138fd05 --notify ioctl:1=0xc138fd0e --log-args ioctl=1 --log-mem ioctl=2:176 --log $log \
    -- "$BASH" --noprofile --norc -c "$2" >/tmp/rf.out 2>/tmp/rf.err
  show "$1" $?
  /usr/bin/python3 -c 'import json,struct,sys
names = {0xc138fd06: "SUSPEND", 0xc138fd04: "REMOVE", 0xc138fd0a: "CLEAR", 0xc138fd05: "RENAME", 0xc138fd0e: "MESSAGE"}
for line in open(sys.argv[1]):
    r = json.loads(line); b = bytes.fromhex(r["memory2"]["hex"])
    flags, = struct.unpack_from("<I", b, 28)
    print("  ioctl %s flags=%#x name=%s" % (names[r["arg1"]], flags & 0x2ffff, b[48:176].split(b"\0")[0].decode()))' $log; }
