D load rf-a --table '0 64 error'; inf rf-a; o clear "dmsetup clear --noudevsync rf-a"; inf rf-a
o wipe "dmsetup wipe_table --noudevsync rf-a"; rt rf-a; inf rf-a
exec 7</dev/dm-$(minor rf-b)
o remove-busy "dmsetup remove --noudevsync rf-b"; ex rf-b
o remove-force-busy "dmsetup remove --noudevsync --force rf-b"; ex rf-b; rt rf-b
o remove-deferred "dmsetup remove --noudevsync --deferred rf-b"; inf rf-b
exec 7<&-; settle; ex rf-b
o remove-multi "dmsetup remove --noudevsync rf-c rf-none rf-d"; ex rf-c; ex rf-d
o suspend-multi "dmsetup suspend --noudevsync rf-none rf-e"; inf rf-e; D resume rf-e
o remove-all "dmsetup remove_all --noudevsync"; r ls-after /usr/sbin/dmsetup ls
D create rf-r --table '0 8 zero' && D create rf-q --table '0 8 zero' || echo SETUP-FAILED
o rename "dmsetup rename --noudevsync rf-r rf-r2"; ex rf-r; ex rf-r2
o setuuid "dmsetup rename --noudevsync --setuuid rf-r2 RF-UUID-R"; inf rf-r2
o setuuid-again "dmsetup rename --noudevsync --setuuid rf-r2 RF-UUID-S"; inf rf-r2
o rename-exists "dmsetup rename --noudevsync rf-r2 rf-q"; ex rf-r2
o rename-long "dmsetup rename --noudevsync rf-r2 $(printf 'n%.0s' {1..130})"; ex rf-r2
o rename-slash "dmsetup rename --noudevsync rf-r2 x/y"; ex rf-r2
o stats-create "dmsetup message --noudevsync rf-q 0 @stats_create - /100"
o stats-list "dmsetup message --noudevsync rf-q 0 @stats_list"
o message-sector "dmsetup message --noudevsync rf-q 5 @stats_list"
o message-bad "dmsetup message --noudevsync rf-q 0 bogus"
D remove_all; detach $d1; echo teardown=ok

